    // https://gist.github.com/TheIcemanCometh/57d0f9ae7b70dcdcc4d9
    override fun onFling(
        e1: MotionEvent?,
        e2: MotionEvent?,
        velocityX: Float,
        velocityY: Float
    ): Boolean {
        if (e1 != null && e2 != null) {
            val diffY = abs(e1.y - e2.y)
            val diffX = abs(e1.x - e2.x)
            if (diffY > SWIPE_MAX_OFF_PATH) {
